import{_ as e,o as i,c as n,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2019-08-21 :: Ceph Testing Meeting","description":"","frontmatter":{"title":"2019-08-21 :: Ceph Testing Meeting","date":"2019-08-21T00:00:00.000Z","updated":"2019-09-06T00:00:00.000Z","tags":["Ceph","测试","代码合并","研发会议","资源配置"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-08-21_-_-_Ceph_Testing_Meeting.md","filePath":"posts/2019/2019-08-21_-_-_Ceph_Testing_Meeting.md","lastUpdated":1780460162000}'),s={name:"posts/2019/2019-08-21_-_-_Ceph_Testing_Meeting.md"};function p(o,t,r,g,_,a){return i(),n("div",null,[...t[0]||(t[0]=[l("<p>Ceph 测试会议纪要</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>会议地点</strong>： 线上会议</p><p><strong>参会人员</strong>： 多位Ceph研发人员及测试人员</p><p><strong>会议主题</strong>： 讨论Ceph项目的进展、测试模块、代码合并及后续行动计划</p><p><strong>会议内容</strong>：</p><p><strong>1. 代码合并与测试模块</strong>：</p><ul><li>目前Ceph项目的代码合并尚未完成，主要问题在于构建集成部分。</li><li>新的Manager模块需要测试，但目前缺乏测试环境和测试方法。</li><li>Sage提到Dan预计会发布新的SEF，这将有助于测试新模块。</li></ul><p><strong>2. 测试环境</strong>：</p><ul><li>目前Ceph项目的测试环境主要针对文档和流程测试，以及与Red Hat OpenShift容器存储产品的集成测试。</li><li>对于Surf产品中的未测试部分，目前没有明确的测试计划。</li></ul><p><strong>3. 人力资源与集成</strong>：</p><ul><li>目前Ceph项目的人力资源紧张，缺乏足够的测试人员。</li><li>集成方面，目前没有计划将Authority和Person模块与其他模块进行整合。</li></ul><p><strong>4. 其他</strong>：</p><ul><li>关于CentOS 8i的迁移，目前尚未完成，预计在CentOS 8发布后进行。</li><li>会议中提到的关于迁移的pull request，由于Python 3迁移问题，该请求已基本废弃。</li></ul><p><strong>决定事项</strong>：</p><ul><li>加快代码合并进度，解决构建集成问题。</li><li>建立新的测试环境和测试方法，确保新模块的稳定性。</li><li>评估人力资源配置，增加测试人员。</li><li>研究Authority和Person模块与其他模块的整合方案。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>由Dan负责发布SEF，并协助测试新模块。</li><li>Alfredo和团队负责优化测试环境和测试方法。</li><li>人力资源部门负责招聘测试人员。</li><li>技术团队评估Authority和Person模块的整合方案。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中多次提到“build integrations”和“container”等关键词，表明构建集成和容器技术是当前Ceph项目关注的重点。</li><li>会议中提到的“Python 3”和“CentOS 8i”等关键词，表明Python 3迁移和CentOS 8i迁移是当前Ceph项目面临的技术挑战。</li></ul>",20)])])}const C=e(s,[["render",p]]);export{h as __pageData,C as default};
